@testable import HideMyData

// MARK: - Fixtures

/// A planted-secret test PDF (see Fixtures/; generated by mkfix.py, the verifier's mk.py/mk2.py, and qpdf).
nonisolated struct Fixture: CustomStringConvertible, Sendable {
    /// Where the secrets' on-page locations can be taken from for pixel checks.
    enum Geometry: Sendable {
        /// The fixture's own text layer is truthful.
        case textLayer
        /// Image-only page laid out exactly like plain.pdf.
        case plainLayout
        /// The text layer is absent, partial or lies: only the OCR check applies.
        case none
    }

    let name: String
    /// Open password, for user-password-protected fixtures.
    var password: String?
    var geometry: Geometry = .textLayer
    /// Whether the page carries the public header that must stay readable.
    var hasHeader = true

    var description: String { name }

    static let secrets = [
        "Johnathan Testerson", "123-45-6789", "secret.person@example.com", "(555) 867-5309", "999-88-7777"
    ]
    /// Fragments that must not be recognisable by OCR anywhere in an export.
    static let secretFragments = ["Johnathan", "Testerson", "123-45", "45-6789", "secret.person", "867-5309", "999-88"]
    static let publicHeader = "PUBLIC HEADER KEEP VISIBLE"

    /// The original matrix.
    static let core: [Fixture] = [
        Fixture(name: "plain"), Fixture(name: "rot90"), Fixture(name: "rot180"), Fixture(name: "rot270"),
        Fixture(name: "offset"), Fixture(name: "crop"), Fixture(name: "croprot"),
        Fixture(name: "owner256"), Fixture(name: "owner128rc4"), Fixture(name: "owner40"),
        Fixture(name: "owner256rot90"), Fixture(name: "user256", password: "userpw"),
        Fixture(name: "scan", geometry: .plainLayout), Fixture(name: "multipage"),
        // Non-integer (A4) page size + /Rotate 90.
        Fixture(name: "a4rot90")
    ]
    /// Scans whose invisible text layer lies (F1: misplaced, F2: too small), or that carry a
    /// little native text (F4: footer / partial layer) so the pixels were never OCR'd.
    static let lyingScans: [Fixture] = [
        Fixture(name: "scan_misaligned", geometry: .none), Fixture(name: "scan_small_layer", geometry: .none),
        Fixture(name: "scan_with_footer", geometry: .none), Fixture(name: "scan_partial_layer", geometry: .none),
        // Image-only page scanned sideways (text runs vertically; small 8 pt line).
        Fixture(name: "scan_only_side", geometry: .none)
    ]
    /// Short / tiny / extreme pages (F3 blur strength, F5 huge page).
    static let oddSizes: [Fixture] = [
        Fixture(name: "short_strip", hasHeader: false), Fixture(name: "blurh70", hasHeader: false),
        Fixture(name: "tiny", hasHeader: false), Fixture(name: "wide", hasHeader: false),
        Fixture(name: "big12000")
    ]
    static let all: [Fixture] = core + lyingScans + oddSizes
    static let permissionRestricted: [Fixture] = all.filter { $0.name.hasPrefix("owner") }

    var url: URL { FixtureLocator.url(for: name) }
}

private nonisolated final class BundleToken {}

nonisolated enum FixtureLocator {
    /// Looks in the test bundle root, then a Fixtures/ subdirectory, then next to this source
    /// file, then $HMD_FIXTURES (swiftc harness).
    static func url(for name: String) -> URL {
        let bundle = Bundle(for: BundleToken.self)
        if let url = bundle.url(forResource: name, withExtension: "pdf") { return url }
        if let url = bundle.url(forResource: name, withExtension: "pdf", subdirectory: "Fixtures") { return url }
        let fm = FileManager.default
        let besideSource = URL(fileURLWithPath: #filePath).deletingLastPathComponent()
            .appendingPathComponent("Fixtures/\(name).pdf")
        if fm.fileExists(atPath: besideSource.path) { return besideSource }
        if let dir = ProcessInfo.processInfo.environment["HMD_FIXTURES"] {
            return URL(fileURLWithPath: dir).appendingPathComponent("\(name).pdf")
        }
        return besideSource
    }
}

func temporaryOutputURL(_ name: String) -> URL {
    let dir = FileManager.default.temporaryDirectory.appendingPathComponent("HideMyDataTests", isDirectory: true)
    try? FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
    return dir.appendingPathComponent("\(name)-\(UUID().uuidString).pdf")
}

// MARK: - Stub detectors

/// Finds the planted secrets by exact string search and reports correct offsets
/// (Character offsets, like the real detector), optionally corrupted.
@MainActor
final class StubDetector: PIIDetecting {
    var needles: [String]
    /// Added to every start/end offset (to simulate a detector whose offsets don't match the text).
    var offsetShift = 0
    /// Extra spans whose text does not exist on the page.
    var phantomTexts: [String] = []
    var failure: Error?
    private(set) var inputs: [String] = []

    init(needles: [String] = Fixture.secrets) {
        self.needles = needles
    }

    func detect(_ text: String) async -> Result<[DetectedSpan], Error> {
        inputs.append(text)
        if let failure { return .failure(failure) }
        var spans: [DetectedSpan] = []
        for needle in needles {
            var from = text.startIndex
            while let r = text.range(of: needle, range: from..<text.endIndex) {
                let s = text.distance(from: text.startIndex, to: r.lowerBound) + offsetShift
                let e = text.distance(from: text.startIndex, to: r.upperBound) + offsetShift
                spans.append(DetectedSpan(category: "test", text: needle, start: s, end: e, confidence: 1))
                from = r.upperBound
            }
        }
        for phantom in phantomTexts {
            spans.append(DetectedSpan(category: "test", text: phantom, start: 0, end: phantom.count, confidence: 1))
        }
        return .success(spans)
    }
}

// MARK: - Expected geometry (computed independently of PDFNormalizer)

/// Where `needle` appears on each page of the ORIGINAL fixture, mapped into displayed space
/// (crop origin removed, /Rotate applied clockwise) using the PDF spec math directly.
@MainActor
func expectedDisplayRects(of needle: String, in fixture: Fixture) -> [Int: [CGRect]] {
    let sourceURL: URL
    switch fixture.geometry {
    case .textLayer: sourceURL = fixture.url
    case .plainLayout: sourceURL = FixtureLocator.url(for: "plain")
    case .none: return [:]
    }
    guard let doc = PDFDocument(url: sourceURL) else { return [:] }
    if doc.isLocked, let pw = fixture.password { _ = doc.unlock(withPassword: pw) }
    var result: [Int: [CGRect]] = [:]
    for selection in doc.findString(needle, withOptions: []) {
        for page in selection.pages {
            let pageIndex = doc.index(for: page)
            let rect = displayRect(selection.bounds(for: page), on: page)
            let shown = CGRect(origin: .zero, size: displayedSize(of: page))
            // Text outside the crop box is not displayed; it must simply not appear.
            guard rect.intersects(shown) else { continue }
            result[pageIndex, default: []].append(rect.intersection(shown))
        }
    }
    return result
}

func displayedSize(of page: PDFPage) -> CGSize {
    let crop = page.bounds(for: .cropBox)
    let r = ((page.rotation % 360) + 360) % 360
    return r == 90 || r == 270 ? CGSize(width: crop.height, height: crop.width) : crop.size
}

/// PDF-spec mapping of a page-space rect to displayed space (origin bottom-left).
func displayRect(_ rect: CGRect, on page: PDFPage) -> CGRect {
    let crop = page.bounds(for: .cropBox)
    let cw = crop.width, ch = crop.height
    let r = ((page.rotation % 360) + 360) % 360
    let corners = [
        CGPoint(x: rect.minX, y: rect.minY), CGPoint(x: rect.maxX, y: rect.minY),
        CGPoint(x: rect.minX, y: rect.maxY), CGPoint(x: rect.maxX, y: rect.maxY)
    ].map { p -> CGPoint in
        let u = p.x - crop.minX, v = p.y - crop.minY
        switch r {
        case 90: return CGPoint(x: v, y: cw - u)
        case 180: return CGPoint(x: cw - u, y: ch - v)
        case 270: return CGPoint(x: ch - v, y: u)
        default: return CGPoint(x: u, y: v)
        }
    }
    let xs = corners.map(\.x), ys = corners.map(\.y)
    return CGRect(x: xs.min()!, y: ys.min()!, width: xs.max()! - xs.min()!, height: ys.max()! - ys.min()!)
}

// MARK: - Pixels (own renderer, independent of the export verifier)

struct RenderedPage {
    let width: Int
    let height: Int
    let scale: CGFloat
    let pixels: [UInt8]
    let image: CGImage

    /// Renders at 2x, reduced so the longest edge stays ≤ 6000 px (huge pages).
    init?(_ page: PDFPage) {
        let box = page.bounds(for: .mediaBox)
        let scale = min(2, 6000 / max(box.width, box.height))
        let w = Int(box.width * scale), h = Int(box.height * scale)
        guard w > 0, h > 0, let ctx = CGContext(
            data: nil, width: w, height: h, bitsPerComponent: 8, bytesPerRow: w * 4,
            space: CGColorSpaceCreateDeviceRGB(), bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
        ) else { return nil }
        ctx.setFillColor(CGColor(red: 1, green: 1, blue: 1, alpha: 1))
        ctx.fill(CGRect(x: 0, y: 0, width: w, height: h))
        ctx.scaleBy(x: scale, y: scale)
        ctx.translateBy(x: -box.minX, y: -box.minY)
        page.draw(with: .mediaBox, to: ctx)
        guard let data = ctx.data, let image = ctx.makeImage() else { return nil }
        width = w; height = h; self.scale = scale; self.image = image
        pixels = Array(UnsafeBufferPointer(start: data.assumingMemoryBound(to: UInt8.self), count: w * h * 4))
    }

    /// Fraction of pixels in a page-space rect (origin bottom-left) darker than `threshold` (0–255 luminance-ish).
    func darkFraction(in rect: CGRect, threshold: Int = 100) -> Double {
        let x0 = max(0, Int(rect.minX * scale)), x1 = min(width, Int(rect.maxX * scale))
        let rowTop = max(0, height - Int(rect.maxY * scale)), rowBottom = min(height, height - Int(rect.minY * scale))
        guard x1 > x0, rowBottom > rowTop else { return 0 }
        var dark = 0
        for row in rowTop..<rowBottom {
            for col in x0..<x1 {
                let i = (row * width + col) * 4
                if (Int(pixels[i]) + Int(pixels[i + 1]) + Int(pixels[i + 2])) / 3 < threshold { dark += 1 }
            }
        }
        return Double(dark) / Double((x1 - x0) * (rowBottom - rowTop))
    }
}

// MARK: - Redactor helpers

@MainActor
func makeRedactor(password: String? = nil, provided: ((String, Bool) -> Void)? = nil) -> PDFRedactor {
    PDFRedactor(passwordProvider: { name, failed in
        provided?(name, failed)
        return password
    })
}

/// Loads, detects with the stub, and returns the redactor (asserting nothing).
@MainActor
func loadAndDetect(_ fixture: Fixture, detector: StubDetector = StubDetector(), style: RedactionStyle = .blackRectangle)
    async -> (PDFRedactor, PDFDetectionReport?) {
    let redactor = makeRedactor(password: fixture.password)
    redactor.redactionStyle = style
    guard redactor.loadPDF(from: fixture.url) else { return (redactor, nil) }
    let report = await redactor.runDetection(using: detector)
    return (redactor, report)
}

// MARK: - Independent OCR of exported pages (Vision directly, not the app's OCREngine)

/// All text Vision recognizes on the image, trying the four orientations (rotated pages).
func recognizedText(in image: CGImage) async -> String {
    let context = CIContext()
    var lines: [String] = []
    for orientation: CGImagePropertyOrientation in [.up, .right, .down, .left] {
        let oriented = CIImage(cgImage: image).oriented(orientation)
        guard let cg = context.createCGImage(oriented, from: oriented.extent) else { continue }
        var request = RecognizeTextRequest()
        request.recognitionLevel = .accurate
        request.usesLanguageCorrection = false
        guard let observations = try? await request.perform(on: cg) else { continue }
        lines += observations.compactMap { $0.topCandidates(1).first?.string }
    }
    return lines.joined(separator: "\n")
}

/// Secret fragments OCR still finds in `text` (case-insensitive, whitespace-insensitive).
func recognizedSecrets(in text: String) -> [String] {
    let folded = text.lowercased().filter { !$0.isWhitespace }
    return Fixture.secretFragments.filter { folded.contains($0.lowercased().filter { !$0.isWhitespace }) }
}

func containsHeader(_ text: String) -> Bool {
    text.lowercased().filter { !$0.isWhitespace }.contains("publicheaderkeepvisible")
}

/// Where Vision sees each planted secret in the ORIGINAL fixture's pixels (page 0, upright),
/// in page space. Independent of any text layer, so it is the ground truth for lying scans.
@MainActor
func ocrSecretRects(in fixture: Fixture) async -> [CGRect] {
    guard let doc = PDFDocument(url: fixture.url), let page = doc.page(at: 0),
          let rendered = RenderedPage(page) else { return [] }
    var request = RecognizeTextRequest()
    request.recognitionLevel = .accurate
    request.usesLanguageCorrection = false
    guard let observations = try? await request.perform(on: rendered.image) else { return [] }
    let box = page.bounds(for: .mediaBox)
    var rects: [CGRect] = []
    for observation in observations {
        guard let candidate = observation.topCandidates(1).first else { continue }
        let line = candidate.string
        for secret in Fixture.secrets {
            guard let range = line.range(of: secret),
                  let region = candidate.boundingBox(for: range) else { continue }
            let n = region.boundingBox.cgRect
            rects.append(CGRect(x: box.minX + n.minX * box.width, y: box.minY + n.minY * box.height,
                                width: n.width * box.width, height: n.height * box.height))
        }
    }
    return rects
}
